def seed_knowledge_and_pricing(db):
    """Seed knowledge base and pricing plans if missing in the database."""
    # 1. Seed Knowledge Base entries
    for item in DEFAULT_KNOWLEDGE_BASE:
        existing = KnowledgeBase.query.filter_by(category=item['category'], title=item['title']).first()
        if not existing:
            kb = KnowledgeBase(
                category=item['category'],
                title=item['title'],
                content=item['content'],
                sort_order=item.get('sort_order', 10),
                is_enabled=True
            )
            db.session.add(kb)
    
    # 2. Seed Pricing Plans
    for plan in DEFAULT_PRICING_PLANS:
        existing = PricingPlan.query.filter_by(plan_name=plan['plan_name']).first()
        if not existing:
            p = PricingPlan(
                plan_name=plan['plan_name'],
                price=plan['price'],
                currency=plan.get('currency', 'INR'),
                features=plan.get('features', []),
                maintenance_price=plan.get('maintenance_price', 0.0),
                sort_order=plan.get('sort_order', 0),
                is_enabled=True
            )
            db.session.add(p)
    
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
